INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.75.0',
  '2026-08-06',
  'Пульт ТВ: смотреть домашние сериалы на приставке',
  E'Новая страница «Пульт ТВ». На домашнем компьютере работает медиаагент, на ТВ-приставке открывается страница плеера, а телефон становится пультом: листать папки, включать серии, ставить паузу, перематывать, переключать серии.\n\nВидео идёт напрямую по локальной сети, минуя сервер, — качество упирается только в домашний вайфай. Через интернет ходят одни команды, поэтому пульт работает и с мобильного.\n\nМузыка — вторым плеером. Поставили сериал на паузу, включили музыку — видео осталось ровно там, где стояло, и возвращается мгновенно.\n\nПапка целиком уходит в очередь: серии идут одна за другой сами, а порядок «человеческий» — вторая серия перед десятой, а не после.\n\nПриставка играет только MP4. Что не подходит — помечено, и одно нажатие ставит файл в очередь на перекодирование; прогресс виден на пульте, а пользоваться им можно дальше. Для больших библиотек есть отдельный скрипт: он же раскладывает файлы по формату Plex.\n\nСтраница выдаётся персонально.',
  E'Прод — ТОЛЬКО шина (internal/tvrelay): пересылает непрозрачный JSON внутри комнаты и ничего о нём не знает. Листинги папок приставка берёт у своего агента по локальной сети напрямую, поэтому ни медиа, ни пути файлов через сервер не проходят, а нагрузка на VPS нулевая.\n\nОтказ от кода с QR: приставка и телефон в одной локальной сети, и достаточно назвать адрес агента. Комната — это строка (по умолчанию адрес машины), нормализуется из «http://192.168.0.226/tv/». Владелец закрепляется при первом подключении пульта: без этого ключ вида «192.168.0.226» угадал бы любой прохожий, ведь шина стоит на общедоступном сервере. Проверено: чужую комнату не занять (409), её не видно в списке и не удалить (404).\n\nВеб-сокет приставки без авторизации — её открывают на телевизоре, где Telegram нет. Пульт подключается по одноразовому пропуску (terminal.Tickets): заголовок Authorization в веб-сокете из браузера не поставить.\n\nПинг раз в 30 с: мобильные сети рвут молчащие соединения, а пульт висит открытым весь фильм. Ping идёт через тот же замок, что и запись, — две параллельные записи в один веб-сокет это паника в gorilla.\n\nПоймано при проверке: play() у элемента БЕЗ источника не отвергается и не выполняется, а висит вечно — кнопка разблокировки звука на приставке из-за этого не срабатывала. Разблокировка звука это само нажатие, проигрывать для неё ничего не нужно.\n\nВёрстка плеера: grid-template-columns с minmax(0,…) — иначе длинные имена файлов растягивают колонку списка и сжимают видео в полоску (у элементов сетки min-width по умолчанию auto).'
);
